import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { String s = br.readLine(); String[] words = s.split(" "); boolean found = false; for (String word : words) { if (word.equals("not")) { found = true; break; } } if (found) { System.out.println("Real Fancy"); } else { System.out.println("regularly fancy"); } } } }